// Keep only new, relevant KEV entries. Dedupe via workflow static data
// (static data persists only for production runs of an ACTIVE workflow).
const LOOKBACK_DAYS = 2;
const MAX_PER_RUN = 5;
// Tune this to your environment's tech stack
const WATCHLIST = ['microsoft', 'fortinet', 'palo alto', 'cisco', 'ivanti', 'citrix',
  'vmware', 'atlassian', 'apache', 'linux', 'google', 'apple', 'okta', 'oracle'];

const feed = $input.first().json;
const state = $getWorkflowStaticData('global');
state.seen = state.seen || [];
const cutoff = Date.now() - LOOKBACK_DAYS * 864e5;

const fresh = (feed.vulnerabilities || [])
  .filter(v => new Date(v.dateAdded).getTime() >= cutoff)
  .filter(v => WATCHLIST.some(w => String(v.vendorProject).toLowerCase().includes(w)))
  .filter(v => !state.seen.includes(v.cveID))
  .slice(0, MAX_PER_RUN);

state.seen = [...state.seen, ...fresh.map(v => v.cveID)].slice(-500);
return fresh.map(v => ({ json: v }));

// Extract the Sigma YAML and prepare GitHub PR metadata.
const OWNER = 'YOUR-GITHUB-USER';   // <- change
const REPO = 'tide-automation';     // <- change
const BASE = 'main';

const src = $('Build Detection Request').all();
return $input.all().map((item, i) => {
  const kev = src[i].json;
  const text = (item.json.content || []).filter(b => b.type === 'text').map(b => b.text).join('')
    .replace(/```ya?ml|```/g, '').trim();
  const slug = String(kev.cveID).toLowerCase();
  return { json: {
    cve: kev.cveID, vendor: kev.vendorProject, product: kev.product, vuln_name: kev.vulnerabilityName,
    ransomware: kev.knownRansomwareCampaignUse,
    owner: OWNER, repo: REPO, base: BASE,
    branch: `detection/${slug}-${Date.now()}`,
    path: `rules/kev/${slug}.yml`,
    sigma: text,
    content_b64: Buffer.from(text + '\n', 'utf8').toString('base64'),
    valid: text.includes('logsource:') && text.includes('detection:') && text.includes('condition:'),
  }};
}).filter(x => x.json.valid);

